@Component("observation-handler")
@ProcessingGroup("observation-processing-group")
public class ObservationEventHandler {
	
	// core constructor
	ObservationEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateObservationEvent
     */
    @EventHandler
    public void handle( CreateObservationEvent event) {
        entityManager.persist(new Observation(event.getObservationId(), event.getCode(), event.getValue(), event.getUnit(), event.getEffectiveDateTime(), event.getEncounter(), event.getPatient(), event.getDevice(), event.getLabResult(), event.getInterpretation()));
    }

    /*
     * @param	event UpdateObservationEvent
     */
    @EventHandler
    public Observation handle( UpdateObservationEvent event) {
    	entityManager.merge(new Observation(event.getObservationId(), event.getCode(), event.getValue(), event.getUnit(), event.getEffectiveDateTime(), event.getEncounter(), event.getPatient(), event.getDevice(), event.getLabResult(), event.getInterpretation()));
    }
    
    /*
     * @param	event DeleteObservationEvent
     */
    @EventHandler
    public void on( DeleteObservationEvent event) {
    	Observation entity = new Observation();
   
    	// ------------------------------------------
    	// apply the ObservationId
    	// ------------------------------------------
    	entity.setObservationId( event.getObservationId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ObservationRepository observationEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ObservationEventHandler.class.getName());

}
